declare p jsonb := $premium_content${"doors":[{"day":1,"kind":"scratch","title":"Бриф вместо телепатии","subtitle":"Получить пригодное ТЗ до первой генерации.","emoji":"🧪","xp":40,"body":"## Бриф вместо телепатии\n\nПолучить пригодное ТЗ до первой генерации.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nВход: [задача], [аудитория], [исходники], [срок]. Верни одностраничный бриф: цель, артефакт, обязательные факты, ограничения, критерии приёмки. Если данных мало, задай только вопросы, ответы на которые меняют результат. Остальное пометь как допущение. После ответов собери бриф и список того, что намеренно не входит в работу.\n```\n\n### Что сохранить\n\nОдна страница брифа и список допущений.\n\n### Проверка результата\n\nДругой человек понимает, какой файл нужно получить и по каким признакам принять работу.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Одна страница брифа и список допущений.\n\nВход: [задача], [аудитория], [исходники], [срок]. Верни одностраничный бриф: цель, артефакт, обязательные факты, ограничения, критерии приёмки. Если данных мало, задай только вопросы, ответы на которые меняют результат. Остальное пометь как допущение. После ответов собери бриф и список того, что намеренно не входит в работу.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Другой человек понимает, какой файл нужно получить и по каким признакам принять работу.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Другой человек понимает, какой файл нужно получить и по каким признакам принять работу."}]},{"day":2,"kind":"story","title":"Разбор референса без копирования","subtitle":"Извлечь визуальные правила, а не чужую работу.","emoji":"🎨","xp":40,"body":"## Разбор референса без копирования\n\nИзвлечь визуальные правила, а не чужую работу.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nВход: [свой референс] и [содержание нового макета]. Разбери сетку, контраст, палитру, типографическую иерархию, свет и ритм. Не копируй персонажа, логотип или фирменную композицию. Предложи три новых направления: тихое, смелое и редакционное. Для каждого дай композицию и причины выбора.\n```\n\n### Что сохранить\n\nТри разных направления с понятными визуальными правилами.\n\n### Проверка результата\n\nМеняется художественное решение, а не только цвет фона.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Три разных направления с понятными визуальными правилами.\n\nВход: [свой референс] и [содержание нового макета]. Разбери сетку, контраст, палитру, типографическую иерархию, свет и ритм. Не копируй персонажа, логотип или фирменную композицию. Предложи три новых направления: тихое, смелое и редакционное. Для каждого дай композицию и причины выбора.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Меняется художественное решение, а не только цвет фона.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Меняется художественное решение, а не только цвет фона."}]},{"day":3,"kind":"scratch","title":"Три хука из одного наблюдения","subtitle":"Начать ролик с конкретного напряжения.","emoji":"🎬","xp":40,"body":"## Три хука из одного наблюдения\n\nНачать ролик с конкретного напряжения.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nФакт: [проверенное наблюдение]. Аудитория: [кто]. Составь 12 первых фраз до 12 слов: через противоречие, узнаваемую ситуацию, наглядный эксперимент и неожиданный вопрос. Не выдумывай статистику и личный опыт. Выбери три фразы, укажи обещание каждой и чем его доказать в ролике.\n```\n\n### Что сохранить\n\n12 хуков, три финалиста и доказательство для каждого.\n\n### Проверка результата\n\nКаждое обещание можно выполнить в пределах 30 секунд.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"12 хуков, три финалиста и доказательство для каждого.\n\nФакт: [проверенное наблюдение]. Аудитория: [кто]. Составь 12 первых фраз до 12 слов: через противоречие, узнаваемую ситуацию, наглядный эксперимент и неожиданный вопрос. Не выдумывай статистику и личный опыт. Выбери три фразы, укажи обещание каждой и чем его доказать в ролике.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Каждое обещание можно выполнить в пределах 30 секунд.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Каждое обещание можно выполнить в пределах 30 секунд."}]},{"day":4,"kind":"arcade","title":"Баг как воспроизводимый эксперимент","subtitle":"Дать кодинг-агенту проверяемую задачу.","emoji":"💻","xp":40,"body":"## Баг как воспроизводимый эксперимент\n\nДать кодинг-агенту проверяемую задачу.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nРепозиторий: [путь]. Симптом: [что происходит]. Воспроизведение: [шаги]. Ожидание: [результат]. Сначала найди участок и предложи минимальную проверку, которая падает до исправления. Затем внеси минимальный патч, покажи дифф и прогони проверку. Не меняй соседние функции ради стиля; неизвестные условия отметь отдельно.\n```\n\n### Что сохранить\n\nШаги воспроизведения, патч и результат проверки.\n\n### Проверка результата\n\nПроверка ловит исходную ошибку и проходит после патча.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Шаги воспроизведения, патч и результат проверки.\n\nРепозиторий: [путь]. Симптом: [что происходит]. Воспроизведение: [шаги]. Ожидание: [результат]. Сначала найди участок и предложи минимальную проверку, которая падает до исправления. Затем внеси минимальный патч, покажи дифф и прогони проверку. Не меняй соседние функции ради стиля; неизвестные условия отметь отдельно.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Проверка ловит исходную ошибку и проходит после патча.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Проверка ловит исходную ошибку и проходит после патча."}]},{"day":5,"kind":"scratch","title":"Паспорт персонажа","subtitle":"Удерживать одного героя в серии кадров.","emoji":"🧩","xp":40,"body":"## Паспорт персонажа\n\nУдерживать одного героя в серии кадров.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nСоздай паспорт персонажа для [сюжет]: силуэт, возрастная группа, форма лица, волосы, одежда, аксессуар-якорь, палитра, характерная поза. Раздели неизменяемые и допускающие вариации признаки. Подготовь промпт для листа: анфас, профиль, три четверти, полный рост. Не добавляй фон, который мешает сравнению.\n```\n\n### Что сохранить\n\nПаспорт и один промпт для character sheet.\n\n### Проверка результата\n\nГероя можно узнать по силуэту и трём неизменяемым деталям.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Паспорт и один промпт для character sheet.\n\nСоздай паспорт персонажа для [сюжет]: силуэт, возрастная группа, форма лица, волосы, одежда, аксессуар-якорь, палитра, характерная поза. Раздели неизменяемые и допускающие вариации признаки. Подготовь промпт для листа: анфас, профиль, три четверти, полный рост. Не добавляй фон, который мешает сравнению.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Героя можно узнать по силуэту и трём неизменяемым деталям.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Героя можно узнать по силуэту и трём неизменяемым деталям."}]},{"day":6,"kind":"quiz","title":"Монтажный лист на 20 секунд","subtitle":"Связать текст, изображение и звук.","emoji":"🎁","xp":40,"body":"## Монтажный лист на 20 секунд\n\nСвязать текст, изображение и звук.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nТема: [тема], один вывод: [вывод]. Сделай монтажный лист на 20 секунд: таймкод, кадр, движение, экранный текст, реплика, звук, исходник. Сумма длительностей ровно 20 секунд. Экранный текст до 7 слов на кадр. Не обещай того, что невозможно показать. Отдельно перечисли нужные ассеты.\n```\n\n### Что сохранить\n\nТаблица сцен и список исходников.\n\n### Проверка результата\n\nТаймкоды сходятся, а смысл понятен даже без звука.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Таблица сцен и список исходников.\n\nТема: [тема], один вывод: [вывод]. Сделай монтажный лист на 20 секунд: таймкод, кадр, движение, экранный текст, реплика, звук, исходник. Сумма длительностей ровно 20 секунд. Экранный текст до 7 слов на кадр. Не обещай того, что невозможно показать. Отдельно перечисли нужные ассеты.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"В монтажном листе сцены на 6, 7 и 9 секунд. Цель — 20 секунд. Что нужно сделать?","options":["Сократить или перераспределить сцены до суммарных 20 секунд","Оставить 22 секунды и написать в описании «20»","Ускорить только музыку"],"correct":0,"explain":"Длительность проверяется по сумме сцен; обещанный формат должен совпадать с экспортом."}]},{"day":7,"kind":"scratch","title":"Антигаллюцинационный шлюз","subtitle":"Отделить факты от красивых догадок.","emoji":"🧪","xp":40,"body":"## Антигаллюцинационный шлюз\n\nОтделить факты от красивых догадок.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nИспользуй только [приложенные документы]. Для каждого важного тезиса дай: утверждение, точный фрагмент-основание, источник и место, что подтверждено и что остаётся неизвестным. Если поддержки нет, напиши «не найдено». Не создавай URL и цитаты. В конце составь список сведений, которые нельзя публиковать без дополнительной проверки.\n```\n\n### Что сохранить\n\nТаблица опоры на источники и список пробелов.\n\n### Проверка результата\n\nКаждый опубликованный факт ведёт к существующему месту источника.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Таблица опоры на источники и список пробелов.\n\nИспользуй только [приложенные документы]. Для каждого важного тезиса дай: утверждение, точный фрагмент-основание, источник и место, что подтверждено и что остаётся неизвестным. Если поддержки нет, напиши «не найдено». Не создавай URL и цитаты. В конце составь список сведений, которые нельзя публиковать без дополнительной проверки.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Каждый опубликованный факт ведёт к существующему месту источника.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Каждый опубликованный факт ведёт к существующему месту источника."}]},{"day":8,"kind":"arcade","title":"Фабрика карточек для своего канала","subtitle":"Из одного материала получить разные полезные форматы.","emoji":"🎨","xp":40,"body":"## Фабрика карточек для своего канала\n\nИз одного материала получить разные полезные форматы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nИсходник: [текст]. Подготовь четыре самостоятельных материала: объяснение одной идеи, разбор частой ошибки, упражнение на 10 минут и чек-лист перед публикацией. Для каждого задай аудиторию, основной тезис и конкретный пример. Не повторяй вступления и не выдавай предполагаемый результат за проведённый кейс.\n```\n\n### Что сохранить\n\nЧетыре черновика с разными читательскими задачами.\n\n### Проверка результата\n\nКаждый материал нужен сам по себе и не пересказывает остальные.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Четыре черновика с разными читательскими задачами.\n\nИсходник: [текст]. Подготовь четыре самостоятельных материала: объяснение одной идеи, разбор частой ошибки, упражнение на 10 минут и чек-лист перед публикацией. Для каждого задай аудиторию, основной тезис и конкретный пример. Не повторяй вступления и не выдавай предполагаемый результат за проведённый кейс.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Каждый материал нужен сам по себе и не пересказывает остальные.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Каждый материал нужен сам по себе и не пересказывает остальные."}]},{"day":9,"kind":"scratch","title":"Радар выгод без ловушек","subtitle":"Понять, подходит ли акция именно тебе.","emoji":"🎬","xp":40,"body":"## Радар выгод · срез 26 октября 2026\n\nЭто подборка официальных условий, а не выданная подписка или персональный промокод. Доступность проверяется на твоём аккаунте. После даты среза условия могут измениться.\n\n### ChatGPT Plus · студенческая акция\n\nЧетыре бесплатных расчётных месяца для подходящих студентов вузов США.\n\nПроверка SheerID; карта нужна. Подписки через магазины приложений не подходят. Далее платное продление. Активировать до 2026-10-31; после этой даты предложение считать истёкшим без новой проверки.\n\n[Официальные условия](https://help.openai.com/en/articles/20001493-chatgpt-back-to-school-offer-for-students)\n\n### GitHub Copilot · Student\n\nБесплатный доступ для подтверждённых студентов GitHub Education.\n\nНужен одобренный статус студента. Лимиты и активацию проверяй в своём аккаунте.\n\n[Официальные условия](https://docs.github.com/en/enterprise-cloud@latest/copilot/how-tos/copilot-on-github/set-up-copilot/enable-copilot/set-up-for-students)\n\n### Perplexity · Education Pro\n\nЛьготный план для подтверждённых студентов и преподавателей.\n\nSheerID; это скидка, а не обещание бесплатного года. Итоговая цена отображается при оформлении.\n\n[Официальные условия](https://www.perplexity.ai/help-center/en/articles/12590157-what-is-education-pro)\n\n### Google AI · студенческие предложения\n\nЕсть разные студенческие варианты; бесплатный Pro trial на 12 месяцев в указанной справке ограничен США.\n\nНе переносить условия США на Казахстан. Студенческий bundle имеет отдельные условия и страны; нужна проверка и платёжный метод.\n\n[Официальные условия](https://support.google.com/googleone/answer/17422238?hl=en)\n\n### Hugging Face · ZeroGPU\n\nГотовые ZeroGPU Spaces можно использовать бесплатно в пределах квоты.\n\nЭто бесплатная инфраструктура с очередями и ограничениями, не промокод на коммерческий тариф.\n\n[Официальные условия](https://huggingface.co/docs/hub/spaces-zerogpu)\n\n### Перед активацией\n\nЗапиши обычную цену, лимиты, дату первого списания и способ отмены. Если не подходишь под условия — пропусти предложение, не покупай чужой верифицированный аккаунт.\n\n\n\n```text\nПроверь [официальная ссылка]. Составь карточку: продукт, что дают, кому доступно, страны, срок активации, нужна ли карта, когда начнутся списания, как отказаться, источник и дата проверки. Отдели бесплатный тариф, пробный период и скидку. Если условия не удалось прочитать, не делай вывод о выгоде.\n```\n","prize":"Радар выгод открыт: пять официальных предложений и проверка условий — ниже. У каждого предложения есть ограничения; сначала проверь страну, верификацию и дату платного продления.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Доступность и автопродление видны до перехода к оплате.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Доступность и автопродление видны до перехода к оплате."}]},{"day":10,"kind":"story","title":"DESIGN.md для следующего макета","subtitle":"Закрепить стиль, который можно повторить.","emoji":"💻","xp":40,"body":"## DESIGN.md для следующего макета\n\nЗакрепить стиль, который можно повторить.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПо [своему проекту] создай DESIGN.md: роли цветов, типографическая шкала, интервалы, сетка, радиусы, компоненты и состояния. Для каждого правила приведи один пример. Отдельно опиши маленький экран, длинный заголовок, ошибку и пустое состояние. Не используй «сделай современно» вместо значений и примеров.\n```\n\n### Что сохранить\n\nФайл с правилами и граничными состояниями.\n\n### Проверка результата\n\nНовый экран вписывается в систему без подбора на глаз.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Файл с правилами и граничными состояниями.\n\nПо [своему проекту] создай DESIGN.md: роли цветов, типографическая шкала, интервалы, сетка, радиусы, компоненты и состояния. Для каждого правила приведи один пример. Отдельно опиши маленький экран, длинный заголовок, ошибку и пустое состояние. Не используй «сделай современно» вместо значений и примеров.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Новый экран вписывается в систему без подбора на глаз.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Новый экран вписывается в систему без подбора на глаз."}]},{"day":11,"kind":"scratch","title":"Референсы для предметной съёмки","subtitle":"Получить варианты кадра для собственного продукта.","emoji":"🧩","xp":40,"body":"## Референсы для предметной съёмки\n\nПолучить варианты кадра для собственного продукта.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПродукт: [описание], материал: [материал], настроение: [настроение]. Предложи три схемы предметной съёмки: каталог, история использования, выразительный крупный план. Укажи объектив как визуальный ориентир, высоту камеры, свет, фон, композицию и место для текста. Не меняй форму товара и надписи на упаковке.\n```\n\n### Что сохранить\n\nТри съёмочных задания и промпта.\n\n### Проверка результата\n\nПродукт остаётся тем же, а кадры решают разные задачи.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Три съёмочных задания и промпта.\n\nПродукт: [описание], материал: [материал], настроение: [настроение]. Предложи три схемы предметной съёмки: каталог, история использования, выразительный крупный план. Укажи объектив как визуальный ориентир, высоту камеры, свет, фон, композицию и место для текста. Не меняй форму товара и надписи на упаковке.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Продукт остаётся тем же, а кадры решают разные задачи.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Продукт остаётся тем же, а кадры решают разные задачи."}]},{"day":12,"kind":"arcade","title":"Режиссёр звука","subtitle":"Не засыпать ролик случайными эффектами.","emoji":"🎁","xp":40,"body":"## Режиссёр звука\n\nНе засыпать ролик случайными эффектами.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nМонтажный лист: [таблица]. Создай звуковую карту: речь, фон, акценты, переходы и тишина. Для каждого элемента дай функцию, время входа и выхода, относительную громкость и критерий проверки. Не подменяй лицензию музыки предположением; для неизвестных прав оставь заглушку.\n```\n\n### Что сохранить\n\nКарта звука с местами осознанной тишины.\n\n### Проверка результата\n\nРечь слышна на динамике телефона, эффект не маскирует смысл.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Карта звука с местами осознанной тишины.\n\nМонтажный лист: [таблица]. Создай звуковую карту: речь, фон, акценты, переходы и тишина. Для каждого элемента дай функцию, время входа и выхода, относительную громкость и критерий проверки. Не подменяй лицензию музыки предположением; для неизвестных прав оставь заглушку.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Речь слышна на динамике телефона, эффект не маскирует смысл.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Речь слышна на динамике телефона, эффект не маскирует смысл."}]},{"day":13,"kind":"scratch","title":"Мини-eval перед сменой модели","subtitle":"Сравнить качество, а не рекламные обещания.","emoji":"🧪","xp":40,"body":"## Мини-eval перед сменой модели\n\nСравнить качество, а не рекламные обещания.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nЗадача: [тип работы]. Составь 8 обезличенных тестов: обычный случай, неполный ввод, противоречие, длинный документ, неверное число, несуществующий источник, ошибка формата, отказ инструмента. Для каждого дай ожидаемые признаки и шкалу 0–2. Вывод о лучшей связке делай только после заполнения таблицы результатами.\n```\n\n### Что сохранить\n\nНабор тестов и пустая таблица оценки.\n\n### Проверка результата\n\nМожно повторить проверку и объяснить каждую оценку.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Набор тестов и пустая таблица оценки.\n\nЗадача: [тип работы]. Составь 8 обезличенных тестов: обычный случай, неполный ввод, противоречие, длинный документ, неверное число, несуществующий источник, ошибка формата, отказ инструмента. Для каждого дай ожидаемые признаки и шкалу 0–2. Вывод о лучшей связке делай только после заполнения таблицы результатами.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Можно повторить проверку и объяснить каждую оценку.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Можно повторить проверку и объяснить каждую оценку."}]},{"day":14,"kind":"quiz","title":"Автоматизация с аварийным выходом","subtitle":"Собрать процесс, который переживает сбой.","emoji":"🎨","xp":40,"body":"## Автоматизация с аварийным выходом\n\nСобрать процесс, который переживает сбой.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПроцесс: [описание]. Разбей его на триггер, вход, проверку данных, действие, подтверждение результата и журнал. Назови ключ идемпотентности, лимиты, повторы, тайм-аут и условие передачи человеку. Для действия с внешним эффектом опиши, что делать, если ответ потерялся после выполнения.\n```\n\n### Что сохранить\n\nСхема процесса и таблица отказов.\n\n### Проверка результата\n\nПовтор события не создаёт второй платёж, пост или письмо.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Схема процесса и таблица отказов.\n\nПроцесс: [описание]. Разбей его на триггер, вход, проверку данных, действие, подтверждение результата и журнал. Назови ключ идемпотентности, лимиты, повторы, тайм-аут и условие передачи человеку. Для действия с внешним эффектом опиши, что делать, если ответ потерялся после выполнения.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Запрос на внешнее действие завершился тайм-аутом. Неизвестно, выполнился ли он. Что безопаснее?","options":["Считать действие невыполненным без проверки","Проверить результат по ключу операции до повтора","Немедленно повторять до успешного ответа"],"correct":1,"explain":"Потерянный ответ не доказывает, что действие не выполнено. Повтор без сверки может создать дубликат."}]},{"day":15,"kind":"scratch","title":"Учебный модуль из первоисточников","subtitle":"Превратить справочник в обучение.","emoji":"🎬","xp":40,"body":"## Учебный модуль из первоисточников\n\nПревратить справочник в обучение.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nИсточники: [свои материалы]. Цель ученика: [наблюдаемое действие]. Собери модуль: короткое объяснение, пример, контрпример, самостоятельное задание, критерий приёмки. Привяжи факты к источникам. Вопросы должны проверять применение, а не узнавание фразы. Не приписывай ученику навык без выполненного задания.\n```\n\n### Что сохранить\n\nОдин завершённый модуль и рубрика проверки.\n\n### Проверка результата\n\nУченик создаёт артефакт, который можно проверить без вкусовой оценки.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Один завершённый модуль и рубрика проверки.\n\nИсточники: [свои материалы]. Цель ученика: [наблюдаемое действие]. Собери модуль: короткое объяснение, пример, контрпример, самостоятельное задание, критерий приёмки. Привяжи факты к источникам. Вопросы должны проверять применение, а не узнавание фразы. Не приписывай ученику навык без выполненного задания.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Ученик создаёт артефакт, который можно проверить без вкусовой оценки.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Ученик создаёт артефакт, который можно проверить без вкусовой оценки."}]},{"day":16,"kind":"arcade","title":"Контент-план как серия экспериментов","subtitle":"Отказаться от одинаковых тридцати постов.","emoji":"💻","xp":40,"body":"## Контент-план как серия экспериментов\n\nОтказаться от одинаковых тридцати постов.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nАудитория: [кто], продукт: [что], цель: [изменение поведения]. Предложи 12 публикаций: проблема, демонстрация, сравнение, разбор ошибки, упражнение и возражение. Для каждой — гипотеза, тезис, доказательство, действие читателя и показатель проверки. Не выдумывай кейсы, отзывы и результаты продаж.\n```\n\n### Что сохранить\n\n12 проверяемых редакционных гипотез.\n\n### Проверка результата\n\nУ каждого поста есть причина существовать и способ оценить пользу.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"12 проверяемых редакционных гипотез.\n\nАудитория: [кто], продукт: [что], цель: [изменение поведения]. Предложи 12 публикаций: проблема, демонстрация, сравнение, разбор ошибки, упражнение и возражение. Для каждой — гипотеза, тезис, доказательство, действие читателя и показатель проверки. Не выдумывай кейсы, отзывы и результаты продаж.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["У каждого поста есть причина существовать и способ оценить пользу.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"У каждого поста есть причина существовать и способ оценить пользу."}]},{"day":17,"kind":"quiz","title":"JSON-контракт для агента","subtitle":"Получать пригодные для обработки ответы.","emoji":"🧩","xp":40,"body":"## JSON-контракт для агента\n\nПолучать пригодные для обработки ответы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nСхема: [JSON Schema]. Вход: [данные]. Верни только JSON по схеме. Неизвестные значения заполняй null только там, где это допускает схема; не придумывай их. Перед ответом проверь обязательные поля, типы, enum и дополнительные ключи. Для ошибок входа используй согласованный объект error.\n```\n\n### Что сохранить\n\nВалидный результат и отдельно тестовые входы.\n\n### Проверка результата\n\nРезультат проходит настоящий валидатор, а не только выглядит как JSON.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Валидный результат и отдельно тестовые входы.\n\nСхема: [JSON Schema]. Вход: [данные]. Верни только JSON по схеме. Неизвестные значения заполняй null только там, где это допускает схема; не придумывай их. Перед ответом проверь обязательные поля, типы, enum и дополнительные ключи. Для ошибок входа используй согласованный объект error.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Схема требует число, но исходные данные его не содержат. Как поступить?","options":["Вернуть строку «неизвестно» вместо числа","Использовать null только если схема допускает его, иначе вернуть согласованную ошибку","Подставить правдоподобное число"],"correct":1,"explain":"Неизвестное значение нельзя выдумывать; нужно соблюдать схему и контракт ошибок."}]},{"day":18,"kind":"story","title":"Честное сравнение двух подписок","subtitle":"Считать стоимость готовой работы.","emoji":"🎁","xp":40,"body":"## Честное сравнение двух подписок\n\nСчитать стоимость готовой работы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nСвязки A и B: [тарифы и лимиты с датой]. Задача: [одинаковый результат]. Создай таблицу: успешные попытки, брак, платные повторения, время ожидания, правки человека и пригодный итог. Не делай вывод по цене одного запроса. Если цены неизвестны, оставь поле пустым и покажи формулу.\n```\n\n### Что сохранить\n\nТаблица расходов на один принятый результат.\n\n### Проверка результата\n\nВ расчёте видны неудачные попытки и труд человека.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Таблица расходов на один принятый результат.\n\nСвязки A и B: [тарифы и лимиты с датой]. Задача: [одинаковый результат]. Создай таблицу: успешные попытки, брак, платные повторения, время ожидания, правки человека и пригодный итог. Не делай вывод по цене одного запроса. Если цены неизвестны, оставь поле пустым и покажи формулу.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["В расчёте видны неудачные попытки и труд человека.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"В расчёте видны неудачные попытки и труд человека."}]},{"day":19,"kind":"scratch","title":"Редактор ясности без смены голоса","subtitle":"Усилить свой текст, сохранив смысл.","emoji":"🧪","xp":40,"body":"## Редактор ясности без смены голоса\n\nУсилить свой текст, сохранив смысл.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nТекст: [текст], читатель: [кто], действие: [что сделать]. Сначала выпиши все факты и обещания. Затем сократи повторы, замени абстракции конкретными действиями и покажи одну улучшенную версию. Не добавляй экспертность, опыт, отзывы или цифры. В конце перечисли изменения смысла, если они понадобились.\n```\n\n### Что сохранить\n\nРедактура, в которой можно проследить каждое изменение.\n\n### Проверка результата\n\nФакты и интонация автора сохранены, читатель понимает следующий шаг.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Редактура, в которой можно проследить каждое изменение.\n\nТекст: [текст], читатель: [кто], действие: [что сделать]. Сначала выпиши все факты и обещания. Затем сократи повторы, замени абстракции конкретными действиями и покажи одну улучшенную версию. Не добавляй экспертность, опыт, отзывы или цифры. В конце перечисли изменения смысла, если они понадобились.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Факты и интонация автора сохранены, читатель понимает следующий шаг.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Факты и интонация автора сохранены, читатель понимает следующий шаг."}]},{"day":20,"kind":"arcade","title":"Сборка лендинга из доказательств","subtitle":"Сначала аргументы, затем красивый экран.","emoji":"🎨","xp":40,"body":"## Сборка лендинга из доказательств\n\nСначала аргументы, затем красивый экран.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПродукт: [описание]. Доказательства: [реальные примеры]. Составь лендинг: ситуация пользователя, результат, демонстрация, состав продукта, ограничения, ответы на возражения и одно основное действие. Для каждого обещания укажи доказательство или отметь пробел. Не вставляй вымышленные отзывы, счётчики и гарантии.\n```\n\n### Что сохранить\n\nКаркас страницы с картой доказательств.\n\n### Проверка результата\n\nНа странице нет обещаний, которые нечем подтвердить.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Каркас страницы с картой доказательств.\n\nПродукт: [описание]. Доказательства: [реальные примеры]. Составь лендинг: ситуация пользователя, результат, демонстрация, состав продукта, ограничения, ответы на возражения и одно основное действие. Для каждого обещания укажи доказательство или отметь пробел. Не вставляй вымышленные отзывы, счётчики и гарантии.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["На странице нет обещаний, которые нечем подтвердить.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"На странице нет обещаний, которые нечем подтвердить."}]},{"day":21,"kind":"quiz","title":"Релиз без сюрприза на телефоне","subtitle":"Проверить то, чем действительно будет пользоваться читатель.","emoji":"🎬","xp":40,"body":"## Релиз без сюрприза на телефоне\n\nПроверить то, чем действительно будет пользоваться читатель.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nАртефакт: [сайт, видео или документ]. Подготовь приёмку: обычный сценарий, маленький экран, длинный текст, пустые данные, ошибка, повторное действие, медленная сеть. Для каждого задай ожидаемый результат и способ проверки. Статус «готово» ставь только после фактической проверки; непроверенное перечисли отдельно.\n```\n\n### Что сохранить\n\nЧек-лист с доказательствами, а не галочками на веру.\n\n### Проверка результата\n\nЕсть проверенный основной сценарий и понятные ограничения.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Чек-лист с доказательствами, а не галочками на веру.\n\nАртефакт: [сайт, видео или документ]. Подготовь приёмку: обычный сценарий, маленький экран, длинный текст, пустые данные, ошибка, повторное действие, медленная сеть. Для каждого задай ожидаемый результат и способ проверки. Статус «готово» ставь только после фактической проверки; непроверенное перечисли отдельно.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Сборка сайта прошла, но основной сценарий на телефоне не проверяли. Какой статус честный?","options":["Сборка успешна; мобильный сценарий пока не проверен","Полностью готово для всех устройств","Проверка не нужна, потому что сборка прошла"],"correct":0,"explain":"Успешная сборка подтверждает сборку, а работоспособность сценария требует отдельной проверки."}]},{"day":22,"kind":"story","title":"Пакет передачи проекта","subtitle":"Чтобы следующий чат не начинал с нуля.","emoji":"💻","xp":40,"body":"## Пакет передачи проекта\n\nЧтобы следующий чат не начинал с нуля.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПроект: [папка]. Подготовь HANDOFF.md: цель, текущие файлы, принятые решения, команды запуска, проверки, известные проблемы и ближайший шаг. Для каждого утверждения о готовности укажи файл или вывод проверки. Не включай ключи, токены, личные данные и содержимое секретных файлов.\n```\n\n### Что сохранить\n\nКомпактная карта проекта для продолжения работы.\n\n### Проверка результата\n\nНовый исполнитель понимает состояние без пересказа всей переписки.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Компактная карта проекта для продолжения работы.\n\nПроект: [папка]. Подготовь HANDOFF.md: цель, текущие файлы, принятые решения, команды запуска, проверки, известные проблемы и ближайший шаг. Для каждого утверждения о готовности укажи файл или вывод проверки. Не включай ключи, токены, личные данные и содержимое секретных файлов.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Новый исполнитель понимает состояние без пересказа всей переписки.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Новый исполнитель понимает состояние без пересказа всей переписки."}]},{"day":23,"kind":"scratch","title":"Одна идея — три языка подачи","subtitle":"Сохранить мысль при изменении формы.","emoji":"🧩","xp":40,"body":"## Одна идея — три языка подачи\n\nСохранить мысль при изменении формы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nТезис: [одна проверенная мысль]. Сделай три версии: объяснение другу на 80 слов, редакционный пост на 150 слов и сценарий из пяти кадров. Сохрани одинаковые факты, ограничения и вывод. После версий покажи таблицу соответствия, где каждый факт появился в каждой форме.\n```\n\n### Что сохранить\n\nТри формы одного материала без смыслового дрейфа.\n\n### Проверка результата\n\nНи одна версия не добавляет новых фактов ради эффектности.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Три формы одного материала без смыслового дрейфа.\n\nТезис: [одна проверенная мысль]. Сделай три версии: объяснение другу на 80 слов, редакционный пост на 150 слов и сценарий из пяти кадров. Сохрани одинаковые факты, ограничения и вывод. После версий покажи таблицу соответствия, где каждый факт появился в каждой форме.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Ни одна версия не добавляет новых фактов ради эффектности.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Ни одна версия не добавляет новых фактов ради эффектности."}]},{"day":24,"kind":"arcade","title":"Финальный производственный спринт","subtitle":"Собрать законченный результат из маленьких инструментов.","emoji":"🎁","xp":40,"body":"## Финальный производственный спринт\n\nСобрать законченный результат из маленьких инструментов.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nЦель: [один полезный продукт]. Ресурсы: [время, инструменты, исходники]. Составь план на два рабочих блока: бриф, прототип, проверка, исправление, экспорт и передача. Определи минимальный законченный результат и стоп-условие. Не запускай платные действия без понятного бюджета. В конце собери папку результата и отчёт по критериям.\n```\n\n### Что сохранить\n\nОдин завершённый продукт и воспроизводимая папка проекта.\n\n### Проверка результата\n\nРезультат открывается, отвечает задаче и прошёл проверку на реальном сценарии.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.","prize":"Один завершённый продукт и воспроизводимая папка проекта.\n\nЦель: [один полезный продукт]. Ресурсы: [время, инструменты, исходники]. Составь план на два рабочих блока: бриф, прототип, проверка, исправление, экспорт и передача. Определи минимальный законченный результат и стоп-условие. Не запускай платные действия без понятного бюджета. В конце собери папку результата и отчёт по критериям.","arcade":{"seconds":30,"cap":40},"quiz":[{"q":"Какой результат действительно подтверждает выполнение этого задания?","options":["Результат открывается, отвечает задаче и прошёл проверку на реальном сценарии.","Ответ звучит уверенно, поэтому можно не проверять","Достаточно написать, что всё готово"],"correct":0,"explain":"Результат открывается, отвечает задаче и прошёл проверку на реальном сценарии."}]}],"rewards":[{"key":"prompt-upgrade","existing_id":9,"doors":3,"title":"Prompt Lab: бриф, факты и живой текст","description":"Три готовых задания с критериями: бриф, опора на источники, редактура без выдумок.","emoji":"🧪","kind":"message","mode":"threshold","payload":{"text":"# Prompt Lab\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Бриф вместо телепатии\n\nПолучить пригодное ТЗ до первой генерации.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nВход: [задача], [аудитория], [исходники], [срок]. Верни одностраничный бриф: цель, артефакт, обязательные факты, ограничения, критерии приёмки. Если данных мало, задай только вопросы, ответы на которые меняют результат. Остальное пометь как допущение. После ответов собери бриф и список того, что намеренно не входит в работу.\n```\n\n### Что сохранить\n\nОдна страница брифа и список допущений.\n\n### Проверка результата\n\nДругой человек понимает, какой файл нужно получить и по каким признакам принять работу.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Антигаллюцинационный шлюз\n\nОтделить факты от красивых догадок.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nИспользуй только [приложенные документы]. Для каждого важного тезиса дай: утверждение, точный фрагмент-основание, источник и место, что подтверждено и что остаётся неизвестным. Если поддержки нет, напиши «не найдено». Не создавай URL и цитаты. В конце составь список сведений, которые нельзя публиковать без дополнительной проверки.\n```\n\n### Что сохранить\n\nТаблица опоры на источники и список пробелов.\n\n### Проверка результата\n\nКаждый опубликованный факт ведёт к существующему месту источника.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Редактор ясности без смены голоса\n\nУсилить свой текст, сохранив смысл.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nТекст: [текст], читатель: [кто], действие: [что сделать]. Сначала выпиши все факты и обещания. Затем сократи повторы, замени абстракции конкретными действиями и покажи одну улучшенную версию. Не добавляй экспертность, опыт, отзывы или цифры. В конце перечисли изменения смысла, если они понадобились.\n```\n\n### Что сохранить\n\nРедактура, в которой можно проследить каждое изменение.\n\n### Проверка результата\n\nФакты и интонация автора сохранены, читатель понимает следующий шаг.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"creative-starter","doors":5,"title":"Creator Kit: хук → герой → монтаж","description":"12 хуков, паспорт персонажа и монтажный лист для короткого ролика.","emoji":"🎬","kind":"message","mode":"threshold","payload":{"text":"# Creator Kit\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Три хука из одного наблюдения\n\nНачать ролик с конкретного напряжения.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nФакт: [проверенное наблюдение]. Аудитория: [кто]. Составь 12 первых фраз до 12 слов: через противоречие, узнаваемую ситуацию, наглядный эксперимент и неожиданный вопрос. Не выдумывай статистику и личный опыт. Выбери три фразы, укажи обещание каждой и чем его доказать в ролике.\n```\n\n### Что сохранить\n\n12 хуков, три финалиста и доказательство для каждого.\n\n### Проверка результата\n\nКаждое обещание можно выполнить в пределах 30 секунд.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Паспорт персонажа\n\nУдерживать одного героя в серии кадров.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nСоздай паспорт персонажа для [сюжет]: силуэт, возрастная группа, форма лица, волосы, одежда, аксессуар-якорь, палитра, характерная поза. Раздели неизменяемые и допускающие вариации признаки. Подготовь промпт для листа: анфас, профиль, три четверти, полный рост. Не добавляй фон, который мешает сравнению.\n```\n\n### Что сохранить\n\nПаспорт и один промпт для character sheet.\n\n### Проверка результата\n\nГероя можно узнать по силуэту и трём неизменяемым деталям.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Монтажный лист на 20 секунд\n\nСвязать текст, изображение и звук.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nТема: [тема], один вывод: [вывод]. Сделай монтажный лист на 20 секунд: таймкод, кадр, движение, экранный текст, реплика, звук, исходник. Сумма длительностей ровно 20 секунд. Экранный текст до 7 слов на кадр. Не обещай того, что невозможно показать. Отдельно перечисли нужные ассеты.\n```\n\n### Что сохранить\n\nТаблица сцен и список исходников.\n\n### Проверка результата\n\nТаймкоды сходятся, а смысл понятен даже без звука.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"radar","doors":1,"title":"Радар выгод: пять официальных точек входа","description":"Условия, ограничения, сроки и проверка выгоды; без вымышленных промокодов.","emoji":"📡","kind":"message","mode":"day","day_from":9,"day_to":12,"payload":{"text":"## Радар выгод · срез 26 октября 2026\n\nЭто подборка официальных условий, а не выданная подписка или персональный промокод. Доступность проверяется на твоём аккаунте. После даты среза условия могут измениться.\n\n### ChatGPT Plus · студенческая акция\n\nЧетыре бесплатных расчётных месяца для подходящих студентов вузов США.\n\nПроверка SheerID; карта нужна. Подписки через магазины приложений не подходят. Далее платное продление. Активировать до 2026-10-31; после этой даты предложение считать истёкшим без новой проверки.\n\n[Официальные условия](https://help.openai.com/en/articles/20001493-chatgpt-back-to-school-offer-for-students)\n\n### GitHub Copilot · Student\n\nБесплатный доступ для подтверждённых студентов GitHub Education.\n\nНужен одобренный статус студента. Лимиты и активацию проверяй в своём аккаунте.\n\n[Официальные условия](https://docs.github.com/en/enterprise-cloud@latest/copilot/how-tos/copilot-on-github/set-up-copilot/enable-copilot/set-up-for-students)\n\n### Perplexity · Education Pro\n\nЛьготный план для подтверждённых студентов и преподавателей.\n\nSheerID; это скидка, а не обещание бесплатного года. Итоговая цена отображается при оформлении.\n\n[Официальные условия](https://www.perplexity.ai/help-center/en/articles/12590157-what-is-education-pro)\n\n### Google AI · студенческие предложения\n\nЕсть разные студенческие варианты; бесплатный Pro trial на 12 месяцев в указанной справке ограничен США.\n\nНе переносить условия США на Казахстан. Студенческий bundle имеет отдельные условия и страны; нужна проверка и платёжный метод.\n\n[Официальные условия](https://support.google.com/googleone/answer/17422238?hl=en)\n\n### Hugging Face · ZeroGPU\n\nГотовые ZeroGPU Spaces можно использовать бесплатно в пределах квоты.\n\nЭто бесплатная инфраструктура с очередями и ограничениями, не промокод на коммерческий тариф.\n\n[Официальные условия](https://huggingface.co/docs/hub/spaces-zerogpu)\n\n### Перед активацией\n\nЗапиши обычную цену, лимиты, дату первого списания и способ отмены. Если не подходишь под условия — пропусти предложение, не покупай чужой верифицированный аккаунт.\n\n\n\n```text\nПроверь [официальная ссылка]. Составь карточку: продукт, что дают, кому доступно, страны, срок активации, нужна ли карта, когда начнутся списания, как отказаться, источник и дата проверки. Отдели бесплатный тариф, пробный период и скидку. Если условия не удалось прочитать, не делай вывод о выгоде.\n```\n"}},{"key":"storyboard-lesson","doors":10,"title":"Закрытый урок: сториборд и его правка","description":"Открывается полноценный урок курса «Ролики с ИИ»: собираем и проверяем сториборд.","emoji":"🎞️","kind":"lesson","mode":"threshold","lesson_title":"Собираем и правим сториборд"},{"key":"coding-kit","doors":12,"title":"Code Kit: баг, eval и JSON-контракт","description":"Три инженерных инструмента: проверяемый патч, тестовый набор, строгий формат данных.","emoji":"💻","kind":"message","mode":"threshold","payload":{"text":"# Code Kit\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Баг как воспроизводимый эксперимент\n\nДать кодинг-агенту проверяемую задачу.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nРепозиторий: [путь]. Симптом: [что происходит]. Воспроизведение: [шаги]. Ожидание: [результат]. Сначала найди участок и предложи минимальную проверку, которая падает до исправления. Затем внеси минимальный патч, покажи дифф и прогони проверку. Не меняй соседние функции ради стиля; неизвестные условия отметь отдельно.\n```\n\n### Что сохранить\n\nШаги воспроизведения, патч и результат проверки.\n\n### Проверка результата\n\nПроверка ловит исходную ошибку и проходит после патча.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Мини-eval перед сменой модели\n\nСравнить качество, а не рекламные обещания.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nЗадача: [тип работы]. Составь 8 обезличенных тестов: обычный случай, неполный ввод, противоречие, длинный документ, неверное число, несуществующий источник, ошибка формата, отказ инструмента. Для каждого дай ожидаемые признаки и шкалу 0–2. Вывод о лучшей связке делай только после заполнения таблицы результатами.\n```\n\n### Что сохранить\n\nНабор тестов и пустая таблица оценки.\n\n### Проверка результата\n\nМожно повторить проверку и объяснить каждую оценку.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## JSON-контракт для агента\n\nПолучать пригодные для обработки ответы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nСхема: [JSON Schema]. Вход: [данные]. Верни только JSON по схеме. Неизвестные значения заполняй null только там, где это допускает схема; не придумывай их. Перед ответом проверь обязательные поля, типы, enum и дополнительные ключи. Для ошибок входа используй согласованный объект error.\n```\n\n### Что сохранить\n\nВалидный результат и отдельно тестовые входы.\n\n### Проверка результата\n\nРезультат проходит настоящий валидатор, а не только выглядит как JSON.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"visual-kit","doors":14,"title":"Visual Kit: референс → стиль → съёмка","description":"Три разных визуальных направления, свой DESIGN.md и предметные кадры.","emoji":"🎨","kind":"message","mode":"threshold","payload":{"text":"# Visual Kit\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Разбор референса без копирования\n\nИзвлечь визуальные правила, а не чужую работу.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nВход: [свой референс] и [содержание нового макета]. Разбери сетку, контраст, палитру, типографическую иерархию, свет и ритм. Не копируй персонажа, логотип или фирменную композицию. Предложи три новых направления: тихое, смелое и редакционное. Для каждого дай композицию и причины выбора.\n```\n\n### Что сохранить\n\nТри разных направления с понятными визуальными правилами.\n\n### Проверка результата\n\nМеняется художественное решение, а не только цвет фона.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## DESIGN.md для следующего макета\n\nЗакрепить стиль, который можно повторить.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПо [своему проекту] создай DESIGN.md: роли цветов, типографическая шкала, интервалы, сетка, радиусы, компоненты и состояния. Для каждого правила приведи один пример. Отдельно опиши маленький экран, длинный заголовок, ошибку и пустое состояние. Не используй «сделай современно» вместо значений и примеров.\n```\n\n### Что сохранить\n\nФайл с правилами и граничными состояниями.\n\n### Проверка результата\n\nНовый экран вписывается в систему без подбора на глаз.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Референсы для предметной съёмки\n\nПолучить варианты кадра для собственного продукта.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПродукт: [описание], материал: [материал], настроение: [настроение]. Предложи три схемы предметной съёмки: каталог, история использования, выразительный крупный план. Укажи объектив как визуальный ориентир, высоту камеры, свет, фон, композицию и место для текста. Не меняй форму товара и надписи на упаковке.\n```\n\n### Что сохранить\n\nТри съёмочных задания и промпта.\n\n### Проверка результата\n\nПродукт остаётся тем же, а кадры решают разные задачи.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"workflow-kit","doors":1,"title":"Workflow Kit: автоматизация, звук, обучение","description":"Процесс с обработкой сбоя, звуковая карта и учебный модуль.","emoji":"🛠️","kind":"message","mode":"day","day_from":13,"day_to":16,"payload":{"text":"# Workflow Kit\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Автоматизация с аварийным выходом\n\nСобрать процесс, который переживает сбой.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПроцесс: [описание]. Разбей его на триггер, вход, проверку данных, действие, подтверждение результата и журнал. Назови ключ идемпотентности, лимиты, повторы, тайм-аут и условие передачи человеку. Для действия с внешним эффектом опиши, что делать, если ответ потерялся после выполнения.\n```\n\n### Что сохранить\n\nСхема процесса и таблица отказов.\n\n### Проверка результата\n\nПовтор события не создаёт второй платёж, пост или письмо.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Режиссёр звука\n\nНе засыпать ролик случайными эффектами.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nМонтажный лист: [таблица]. Создай звуковую карту: речь, фон, акценты, переходы и тишина. Для каждого элемента дай функцию, время входа и выхода, относительную громкость и критерий проверки. Не подменяй лицензию музыки предположением; для неизвестных прав оставь заглушку.\n```\n\n### Что сохранить\n\nКарта звука с местами осознанной тишины.\n\n### Проверка результата\n\nРечь слышна на динамике телефона, эффект не маскирует смысл.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Учебный модуль из первоисточников\n\nПревратить справочник в обучение.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nИсточники: [свои материалы]. Цель ученика: [наблюдаемое действие]. Собери модуль: короткое объяснение, пример, контрпример, самостоятельное задание, критерий приёмки. Привяжи факты к источникам. Вопросы должны проверять применение, а не узнавание фразы. Не приписывай ученику навык без выполненного задания.\n```\n\n### Что сохранить\n\nОдин завершённый модуль и рубрика проверки.\n\n### Проверка результата\n\nУченик создаёт артефакт, который можно проверить без вкусовой оценки.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"editorial-kit","doors":18,"title":"Editorial Kit: серия, лендинг, три формата","description":"План редакционных экспериментов, каркас лендинга и адаптация одной мысли.","emoji":"🗂️","kind":"message","mode":"threshold","payload":{"text":"# Editorial Kit\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Контент-план как серия экспериментов\n\nОтказаться от одинаковых тридцати постов.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nАудитория: [кто], продукт: [что], цель: [изменение поведения]. Предложи 12 публикаций: проблема, демонстрация, сравнение, разбор ошибки, упражнение и возражение. Для каждой — гипотеза, тезис, доказательство, действие читателя и показатель проверки. Не выдумывай кейсы, отзывы и результаты продаж.\n```\n\n### Что сохранить\n\n12 проверяемых редакционных гипотез.\n\n### Проверка результата\n\nУ каждого поста есть причина существовать и способ оценить пользу.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Сборка лендинга из доказательств\n\nСначала аргументы, затем красивый экран.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПродукт: [описание]. Доказательства: [реальные примеры]. Составь лендинг: ситуация пользователя, результат, демонстрация, состав продукта, ограничения, ответы на возражения и одно основное действие. Для каждого обещания укажи доказательство или отметь пробел. Не вставляй вымышленные отзывы, счётчики и гарантии.\n```\n\n### Что сохранить\n\nКаркас страницы с картой доказательств.\n\n### Проверка результата\n\nНа странице нет обещаний, которые нечем подтвердить.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Одна идея — три языка подачи\n\nСохранить мысль при изменении формы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nТезис: [одна проверенная мысль]. Сделай три версии: объяснение другу на 80 слов, редакционный пост на 150 слов и сценарий из пяти кадров. Сохрани одинаковые факты, ограничения и вывод. После версий покажи таблицу соответствия, где каждый факт появился в каждой форме.\n```\n\n### Что сохранить\n\nТри формы одного материала без смыслового дрейфа.\n\n### Проверка результата\n\nНи одна версия не добавляет новых фактов ради эффектности.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"budget-kit","doors":1,"title":"Budget Kit: стоимость готового результата","description":"Формула расходов, таблица сравнения и карта передачи проекта.","emoji":"🧮","kind":"message","mode":"day","day_from":17,"day_to":20,"payload":{"text":"# Budget & Handoff\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Честное сравнение двух подписок\n\nСчитать стоимость готовой работы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nСвязки A и B: [тарифы и лимиты с датой]. Задача: [одинаковый результат]. Создай таблицу: успешные попытки, брак, платные повторения, время ожидания, правки человека и пригодный итог. Не делай вывод по цене одного запроса. Если цены неизвестны, оставь поле пустым и покажи формулу.\n```\n\n### Что сохранить\n\nТаблица расходов на один принятый результат.\n\n### Проверка результата\n\nВ расчёте видны неудачные попытки и труд человека.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Пакет передачи проекта\n\nЧтобы следующий чат не начинал с нуля.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПроект: [папка]. Подготовь HANDOFF.md: цель, текущие файлы, принятые решения, команды запуска, проверки, известные проблемы и ближайший шаг. Для каждого утверждения о готовности укажи файл или вывод проверки. Не включай ключи, токены, личные данные и содержимое секретных файлов.\n```\n\n### Что сохранить\n\nКомпактная карта проекта для продолжения работы.\n\n### Проверка результата\n\nНовый исполнитель понимает состояние без пересказа всей переписки.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"release-kit","doors":21,"title":"Release Kit: приёмка и передача","description":"Чек-лист настоящего релиза и HANDOFF.md для продолжения проекта.","emoji":"🚀","kind":"message","mode":"threshold","payload":{"text":"# Release Kit\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Релиз без сюрприза на телефоне\n\nПроверить то, чем действительно будет пользоваться читатель.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nАртефакт: [сайт, видео или документ]. Подготовь приёмку: обычный сценарий, маленький экран, длинный текст, пустые данные, ошибка, повторное действие, медленная сеть. Для каждого задай ожидаемый результат и способ проверки. Статус «готово» ставь только после фактической проверки; непроверенное перечисли отдельно.\n```\n\n### Что сохранить\n\nЧек-лист с доказательствами, а не галочками на веру.\n\n### Проверка результата\n\nЕсть проверенный основной сценарий и понятные ограничения.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Пакет передачи проекта\n\nЧтобы следующий чат не начинал с нуля.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nПроект: [папка]. Подготовь HANDOFF.md: цель, текущие файлы, принятые решения, команды запуска, проверки, известные проблемы и ближайший шаг. Для каждого утверждения о готовности укажи файл или вывод проверки. Не включай ключи, токены, личные данные и содержимое секретных файлов.\n```\n\n### Что сохранить\n\nКомпактная карта проекта для продолжения работы.\n\n### Проверка результата\n\nНовый исполнитель понимает состояние без пересказа всей переписки.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}},{"key":"final-kit","doors":24,"title":"Финальный набор: от идеи до готовой папки","description":"Производственный спринт, контент из исходника и бриф с критериями.","emoji":"👑","kind":"message","mode":"threshold","payload":{"text":"# Production Sprint\n\nГотовый набор OG CRE8R². Замени ввод своими данными; оценивай сохранённый результат, а не уверенность ответа.\n\n## Финальный производственный спринт\n\nСобрать законченный результат из маленьких инструментов.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nЦель: [один полезный продукт]. Ресурсы: [время, инструменты, исходники]. Составь план на два рабочих блока: бриф, прототип, проверка, исправление, экспорт и передача. Определи минимальный законченный результат и стоп-условие. Не запускай платные действия без понятного бюджета. В конце собери папку результата и отчёт по критериям.\n```\n\n### Что сохранить\n\nОдин завершённый продукт и воспроизводимая папка проекта.\n\n### Проверка результата\n\nРезультат открывается, отвечает задаче и прошёл проверку на реальном сценарии.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Фабрика карточек для своего канала\n\nИз одного материала получить разные полезные форматы.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nИсходник: [текст]. Подготовь четыре самостоятельных материала: объяснение одной идеи, разбор частой ошибки, упражнение на 10 минут и чек-лист перед публикацией. Для каждого задай аудиторию, основной тезис и конкретный пример. Не повторяй вступления и не выдавай предполагаемый результат за проведённый кейс.\n```\n\n### Что сохранить\n\nЧетыре черновика с разными читательскими задачами.\n\n### Проверка результата\n\nКаждый материал нужен сам по себе и не пересказывает остальные.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём.\n\n---\n\n## Бриф вместо телепатии\n\nПолучить пригодное ТЗ до первой генерации.\n\n### Что подготовить\n\nПодставь свои исходники в квадратные скобки. Если работаешь с чужими данными, сначала убери персональную информацию.\n\n### Готовое задание\n\n```text\nВход: [задача], [аудитория], [исходники], [срок]. Верни одностраничный бриф: цель, артефакт, обязательные факты, ограничения, критерии приёмки. Если данных мало, задай только вопросы, ответы на которые меняют результат. Остальное пометь как допущение. После ответов собери бриф и список того, что намеренно не входит в работу.\n```\n\n### Что сохранить\n\nОдна страница брифа и список допущений.\n\n### Проверка результата\n\nДругой человек понимает, какой файл нужно получить и по каким признакам принять работу.\n\nСохрани исходный ввод, итоговый файл и одну заметку о том, что пришлось исправить. Это превратит удачный ответ в повторяемый рабочий приём."}}]}$premium_content$::jsonb; d jsonb; r jsonb; rid bigint; target_lesson bigint; mapping jsonb := '{}'::jsonb; updated_doors integer:=0; preserved_doors integer:=0;
begin
 if exists(select 1 from public.settings where key='advent_premium:2026-10-26-v1') then return; end if;
 if not exists(select 1 from public.advent_rewards where id=9 and kind='message') then raise exception 'Expected existing prompt reward'; end if;
 for d in select value from jsonb_array_elements(p->'doors') loop
  if exists(select 1 from public.advent_opens where day=(d->>'day')::integer) then preserved_doors:=preserved_doors+1; continue; end if;
  update public.advent_doors set kind=d->>'kind',title=d->>'title',subtitle=d->>'subtitle',emoji=d->>'emoji',body=d->>'body',quiz=d->'quiz',prize=d->>'prize',arcade=d->'arcade',xp=(d->>'xp')::integer,updated_at=now() where day=(d->>'day')::integer;
  if not found then raise exception 'Missing door %',d->>'day'; end if;
  updated_doors:=updated_doors+1;
 end loop;
 for r in select value from jsonb_array_elements(p->'rewards') loop
  if r->>'existing_id' is not null then
   rid:=(r->>'existing_id')::bigint;
   -- Upgrade the already-issued message in place, retaining all award codes.
   update public.advent_rewards set title=r->>'title',description=r->>'description',emoji=r->>'emoji',payload=r->'payload' where id=rid and kind='message';
  else
   if r->>'kind'='lesson' then
    select id into strict target_lesson from public.lessons where title=r->>'lesson_title' and course_id=(select id from public.courses where title='Ролики с ИИ: от идеи до MP4') and not free_preview;
    r:=jsonb_set(r,'{payload}',jsonb_build_object('lesson_id',target_lesson));
   end if;
   insert into public.advent_rewards(doors,title,description,emoji,stock,position,kind,payload,mode,day_from,day_to)
   values((r->>'doors')::integer,r->>'title',r->>'description',r->>'emoji',null,10+(select count(*)::integer from jsonb_object_keys(mapping)),r->>'kind',r->'payload',r->>'mode',(r->>'day_from')::integer,(r->>'day_to')::integer) returning id into rid;
  end if;
  mapping:=mapping||jsonb_build_object(r->>'key',rid);
 end loop;
 update public.advent_rewards set title='MCP на практике: закрытый урок',description='Полный урок курса «Ролики с ИИ»: подключение инструментов и проверка рабочего процесса.' where id=10 and kind='lesson';
 insert into public.settings(key,value) values('advent_premium:2026-10-26-v1',jsonb_build_object('updated_doors',updated_doors,'preserved_opened_doors',preserved_doors,'rewards',mapping,'date','2026-10-26'));
end $premium_import$;
commit;
select value from public.settings where key='advent_premium:2026-10-26-v1';
